fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to its index in the week,
    // where Sunday = 0, Monday = 1, ..., Saturday = 6
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => panic!("Invalid day abbreviation"),
    };

    // Calculate days until next Sunday.
    // If today is Sunday (0), result should be 7.
    let days_until_sunday = (7 - day_index) % 7;
    if days_until_sunday == 0 { 7 } else { days_until_sunday }
}